import{_ as i,o as t,c as l,a0 as a}from"./chunks/framework.DQOulFGV.js";const e="data:image/svg+xml;base64,",g="data:image/svg+xml;base64,",j=JSON.parse('{"title":"第1章 主从复制","description":"","frontmatter":{},"headers":[],"relativePath":"redis/04-high-availability/chapter-01-replication.md","filePath":"redis/04-high-availability/chapter-01-replication.md"}'),d={name:"redis/04-high-availability/chapter-01-replication.md"};function Z(m,I,s,h,c,C){return t(),l("div",null,[...I[0]||(I[0]=[a('<h1 id="第1章-主从复制" tabindex="-1">第1章 主从复制 <a class="header-anchor" href="#第1章-主从复制" aria-label="Permalink to &quot;第1章 主从复制&quot;">​</a></h1><blockquote><p>单机 Redis 存在单点故障与读写瓶颈。主从复制让数据在多个节点间同步，是哨兵与集群的基石。本章讲解主从复制的同步流程、读写分离与局限。</p></blockquote><hr><h2 id="_1-1-为什么需要主从复制" tabindex="-1">1.1 为什么需要主从复制 <a class="header-anchor" href="#_1-1-为什么需要主从复制" aria-label="Permalink to &quot;1.1 为什么需要主从复制&quot;">​</a></h2><p>单机 Redis 面临三个问题：</p><table tabindex="0"><thead><tr><th style="text-align:left;">问题</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">单点故障</td><td style="text-align:left;">主节点宕机，服务不可用</td></tr><tr><td style="text-align:left;">读瓶颈</td><td style="text-align:left;">所有请求都压在一个节点上</td></tr><tr><td style="text-align:left;">容量受限</td><td style="text-align:left;">单机内存有上限</td></tr></tbody></table><p>主从复制引入「一主多从」结构：主节点负责写，从节点复制数据并分担读请求。</p><p><img src="'+e+'" alt="主从复制一主多从架构"></p><hr><h2 id="_1-2-同步流程" tabindex="-1">1.2 同步流程 <a class="header-anchor" href="#_1-2-同步流程" aria-label="Permalink to &quot;1.2 同步流程&quot;">​</a></h2><p>主从同步使用 <code>PSYNC</code> 命令，分为全量同步与增量同步。</p><h3 id="全量同步" tabindex="-1">全量同步 <a class="header-anchor" href="#全量同步" aria-label="Permalink to &quot;全量同步&quot;">​</a></h3><p>首次连接时，从节点复制主节点的全部数据：</p><p><img src="'+g+`" alt="主从全量同步流程"></p><p>全量同步步骤：</p><ol><li>从节点发送 <code>PSYNC</code>，主节点 BGSAVE 生成 RDB 快照</li><li>主节点把 RDB 发送给从节点，从节点加载</li><li>加载期间主节点的写命令进入复制缓冲区</li><li>RDB 加载完后，主节点把缓冲区的增量命令发给从节点</li></ol><h3 id="增量同步" tabindex="-1">增量同步 <a class="header-anchor" href="#增量同步" aria-label="Permalink to &quot;增量同步&quot;">​</a></h3><p>断线重连后，只同步断开期间的增量数据。主从各自维护一个「复制偏移量」和「复制积压缓冲区（repl_backlog）」：</p><table tabindex="0"><thead><tr><th style="text-align:left;">概念</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">复制偏移量</td><td style="text-align:left;">记录已复制了多少字节数据</td></tr><tr><td style="text-align:left;">积压缓冲区</td><td style="text-align:left;">主节点保存最近一段写命令的环形缓冲</td></tr></tbody></table><p>重连时从节点带上自己的偏移量，若该偏移量还在积压缓冲区范围内，就只补发缺失部分；否则需要全量同步。</p><hr><h2 id="_1-3-读写分离与异步复制" tabindex="-1">1.3 读写分离与异步复制 <a class="header-anchor" href="#_1-3-读写分离与异步复制" aria-label="Permalink to &quot;1.3 读写分离与异步复制&quot;">​</a></h2><h3 id="读写分离" tabindex="-1">读写分离 <a class="header-anchor" href="#读写分离" aria-label="Permalink to &quot;读写分离&quot;">​</a></h3><p>主节点写、从节点读，把读请求分摊到从节点：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 从节点配置</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">replicaof</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 主节点IP</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6379</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 指定主节点</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">replica-read-only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 从节点只读</span></span></code></pre></div><h3 id="异步复制" tabindex="-1">异步复制 <a class="header-anchor" href="#异步复制" aria-label="Permalink to &quot;异步复制&quot;">​</a></h3><p>Redis 的复制是<strong>异步</strong>的：主节点写完就返回，不等待从节点确认。这意味着主从之间存在短暂的数据不一致。</p><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">高性能</td><td style="text-align:left;">主节点不等待从节点，写入延迟低</td></tr><tr><td style="text-align:left;">可能丢数据</td><td style="text-align:left;">主节点宕机时，未同步的数据丢失</td></tr><tr><td style="text-align:left;">弱一致</td><td style="text-align:left;">读从节点可能读到旧数据</td></tr></tbody></table><blockquote><p>异步复制决定了「主从 + 读写分离」无法提供强一致。如果业务要求读到的数据必须是最新的，就不能把读请求分流到从节点。</p></blockquote><hr><h2 id="_1-4-局限" tabindex="-1">1.4 局限 <a class="header-anchor" href="#_1-4-局限" aria-label="Permalink to &quot;1.4 局限&quot;">​</a></h2><p>主从复制解决了「读扩展」与「数据冗余」，但仍有明显局限：</p><table tabindex="0"><thead><tr><th style="text-align:left;">局限</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">无法自动故障转移</td><td style="text-align:left;">主节点宕机需手动切换，服务中断</td></tr><tr><td style="text-align:left;">写无法扩展</td><td style="text-align:left;">写仍只在主节点，写瓶颈未解决</td></tr><tr><td style="text-align:left;">可能脑裂</td><td style="text-align:left;">主从网络分区时，可能出现多个主节点</td></tr></tbody></table><p>主从复制无法自动故障转移的问题，由哨兵（第 2 章）解决；写无法水平扩展的问题，由集群（第 3 章）解决。</p>`,34)])])}const n=i(d,[["render",Z]]);export{j as __pageData,n as default};
